 'servicios_turisticos'=>['label'=>'Servicios','fields'=>['nombre'=>['Nombre','text',180,true],'tipo'=>['Tipo','select',['hotel'=>'Hotel / alojamiento','restaurante'=>'Restaurante','transporte'=>'Transporte'],true],'ubicacion_id'=>['Ubicación','relation','ubicaciones',false],'descripcion'=>['Descripción','textarea',6000,true],'telefono'=>['Teléfono','text',40,false],'direccion'=>['Dirección','text',250,false],'sitio_web'=>['Sitio web (HTTPS)','url',1000,false],'fuente_url'=>['Fuente (HTTPS)','url',1000,true],'verificado'=>['Fuente cotejada','check'],'publicado'=>['Publicado','check']]],
 'rutas_turisticas'=>['label'=>'Rutas','fields'=>['nombre'=>['Nombre','text',180,true],'descripcion'=>['Descripción','textarea',6000,true],'modo'=>['Modalidad','select',['peatonal'=>'Peatonal','vehicular'=>'Vehicular'],true],'duracion_min'=>['Duración estimada por la fuente (min)','integer',[1,100000],false],'fuente_url'=>['Fuente del itinerario (HTTPS)','url',1000,true],'verificado'=>['Itinerario cotejado','check'],'publicado'=>['Publicado','check']]],
 'puntos_ruta'=>['label'=>'Puntos de ruta','fields'=>['ruta_id'=>['Ruta','relation','rutas_turisticas',true],'ubicacion_id'=>['Ubicación','relation','ubicaciones',true],'orden'=>['Orden de parada','integer',[1,10000],true]]],
 'usuarios'=>['label'=>'Usuarios','admin'=>true,'fields'=>['nombre'=>['Nombre','text',120,true],'email'=>['Correo electrónico','email',190,true],'rol_id'=>['Rol','relation','roles',true],'password'=>['Contraseña (12–72 bytes; vacía conserva la actual)','password',72,false],'activo'=>['Cuenta activa','check']]],
