function admin_dispatch(string $route):void {
 $user=current_user();if(!$user)redirect('?page=login');
 if($route==='report') {if($user['rol']!=='administrador')fail_page('Acceso restringido','Solo los administradores pueden consultar reportes.',403);report_page();return;}
 $defs=entities();$entity=query_string('entity');
 if($entity===''||$entity==='dashboard'){page('Panel de gestión',fn()=>admin_dashboard($user,$defs));return;}
 if(!isset($defs[$entity]))fail_page('Módulo no encontrado','El módulo solicitado no existe.',404);
 $def=$defs[$entity];if(($def['admin']??false)&&$user['rol']!=='administrador')fail_page('Acceso restringido','Tu rol no tiene permisos para gestionar usuarios.',403);
 $id=filter_var(query_string('id'),FILTER_VALIDATE_INT)?:0;$action=query_string('action');
 if($_SERVER['REQUEST_METHOD']==='POST') {
  check_csrf();$id=filter_var(input_string('id'),FILTER_VALIDATE_INT)?:0;$action=input_string('action');
  try {
   if(!in_array($action,['save','delete'],true))throw new DomainException('Acción no válida.');
   if($id<0)throw new DomainException('Identificador no válido.');
   $data=$action==='save'?validate_entity($entity,$def,$id):[];
   db()->beginTransaction();
   if($entity==='usuarios'){
    // Serializar cambios de cuentas y proteger administradores activos.
    $admins=rows('SELECT id FROM usuarios WHERE rol_id=1 AND activo=1 ORDER BY id FOR UPDATE');
    $old=$id?one('SELECT * FROM usuarios WHERE id=? FOR UPDATE',[$id]):null;
    if($id===$user['id']&&($action==='delete'||($data['activo']??0)!==1||(int)($data['rol_id']??0)!==1))throw new DomainException('No puedes eliminar, desactivar ni degradar tu propia cuenta.');
    if($old&&$old['rol_id']==1&&$old['activo']&&count($admins)<=1&&($action==='delete'||!($data['activo']??0)||(int)($data['rol_id']??0)!==1))throw new DomainException('Debe conservarse un administrador activo.');
   }
   if($id&&!one("SELECT id FROM `$entity` WHERE id=? FOR UPDATE",[$id]))throw new DomainException('El registro ya no existe.');
   if($action==='delete'){if(!$id)throw new DomainException('Selecciona un registro.');execute("DELETE FROM `$entity` WHERE id=?",[$id]);}
   elseif($id){$fields=array_keys($data);execute("UPDATE `$entity` SET ".implode(',',array_map(fn($f)=>"`$f`=?",$fields)).' WHERE id=?',[...array_values($data),$id]);}
   else{$fields=array_keys($data);execute("INSERT INTO `$entity` (`".implode('`,`',$fields).'`) VALUES ('.implode(',',array_fill(0,count($fields),'?')).')',array_values($data));}
   db()->commit();flash($action==='delete'?'Registro eliminado.':'Registro guardado.');redirect('?page=admin&entity='.$entity);
  }catch(DomainException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}
  catch(PDOException $ex){if(db()->inTransaction())db()->rollBack();if(str_starts_with((string)$ex->getCode(),'23'))$error='No se pudo guardar: hay un valor duplicado o el registro está relacionado con otros datos. Revisa las referencias antes de eliminarlo.';else throw $ex;}
  http_response_code(422);
  page($def['label'],fn()=>admin_form($user,$defs,$entity,$def,$id,$error,$_POST));return;
 }
 if($action==='edit'||$action==='new') { $record=$id?one("SELECT * FROM `$entity` WHERE id=?",[$id]):[];if($id&&!$record)fail_page('Registro no encontrado','El registro solicitado no existe.',404);page($def['label'],fn()=>admin_form($user,$defs,$entity,$def,$id,'',$record));return;}
 page($def['label'],fn()=>admin_list($user,$defs,$entity,$def));
}
function validate_entity(string $entity,array $def,int $id):array {
 $data=[];
 foreach($def['fields'] as $key=>$field){[$label,$type]=$field;$value=$type==='password'?($_POST[$key]??''):input_string($key);if(!is_string($value))throw new DomainException('Formato de campo no válido.');$required=$field[3]??false;
  if($type==='check'){$data[$key]=isset($_POST[$key])?1:0;continue;}
  if($type==='password') {if($value===''&&$id)continue;if(strlen($value)<12||strlen($value)>72)throw new DomainException('La contraseña debe tener entre 12 y 72 bytes.');$data['password_hash']=password_hash($value,PASSWORD_DEFAULT);continue;}
  if($value===''){if($required)throw new DomainException($label.': este campo es obligatorio.');$data[$key]=null;continue;}
  if(in_array($type,['integer','relation'],true)){if(!ctype_digit($value))throw new DomainException($label.': usa un entero positivo.');$n=(int)$value;if($type==='integer'&&($n<$field[2][0]||$n>$field[2][1]))throw new DomainException($label.': fuera del rango permitido.');if($type==='relation'&&!one('SELECT id FROM `'.$field[2].'` WHERE id=?',[$n]))throw new DomainException($label.': selecciona una referencia existente.');$data[$key]=$n;continue;}
  if($type==='decimal'){if(!is_numeric($value)||!is_finite((float)$value)||(float)$value<$field[2][0]||(float)$value>$field[2][1])throw new DomainException($label.': valor fuera del rango permitido.');$data[$key]=$value;continue;}
  if($type==='select'){if(!isset($field[2][$value]))throw new DomainException($label.': opción no válida.');}
  else {if(mb_strlen($value)>$field[2])throw new DomainException($label.': el texto supera la longitud permitida.');if($type==='email'&&!filter_var($value,FILTER_VALIDATE_EMAIL))throw new DomainException('Correo electrónico no válido.');if($type==='url'&&!valid_https($value))throw new DomainException($label.': utiliza una URL HTTPS completa.');}
  $data[$key]=$value;
 }
 if($entity==='ubicaciones'&&!empty($data['verificado'])&&empty($_POST['confirmar_territorio']))throw new DomainException('Confirma que las coordenadas y la jurisdicción fueron cotejadas, sin utilizar datos de ejemplo.');
 if($entity==='rutas_turisticas'&&!empty($data['verificado'])) {if(!$id)throw new DomainException('Guarda primero la ruta sin verificar, añade al menos dos puntos verificados y después verifica el itinerario.');$points=rows('SELECT u.verificado FROM puntos_ruta p JOIN ubicaciones u ON u.id=p.ubicacion_id WHERE p.ruta_id=?',[$id]);if(count($points)<2||array_filter($points,fn($p)=>!$p['verificado']))throw new DomainException('Una ruta verificada necesita al menos dos puntos con ubicaciones cotejadas.');}
 if($entity==='puntos_ruta'){$r=one('SELECT verificado FROM rutas_turisticas WHERE id=?',[$data['ruta_id']]);$u=one('SELECT verificado FROM ubicaciones WHERE id=?',[$data['ubicacion_id']]);if($r&&$r['verificado']&&(!$u||!$u['verificado']))throw new DomainException('No puedes añadir un punto sin verificar a una ruta verificada.');}
 return $data;
}
function admin_shell(array $user,array $defs,string $active,callable $body):void { ?><section class="container admin-layout"><aside class="admin-sidebar"><span class="eyebrow">GESTIÓN DEL TERRITORIO</span><h2>Tu espacio.</h2><a href="<?=e(url('?page=admin'))?>" <?=$active===''?'aria-current="page"':''?>>Resumen</a><?php foreach($defs as $key=>$d):if(($d['admin']??false)&&$user['rol']!=='administrador')continue;?><a <?=$active===$key?'aria-current="page"':''?> href="<?=e(url('?page=admin&entity='.$key))?>"><?=e($d['label'])?></a><?php endforeach;if($user['rol']==='administrador'):?><a href="<?=e(url('?page=report'))?>">Reportes de visitas</a><?php endif;?><hr><small><?=e($user['nombre'])?> · <?=e($user['rol'])?></small><form method="post" action="<?=e(url('?page=logout'))?>"><?=csrf()?><button class="text-button">Cerrar sesión →</button></form></aside><div class="admin-content"><?php $body();?></div></section><?php }
function admin_dashboard(array $user,array $defs):void {admin_shell($user,$defs,'',function()use($user){?><span class="eyebrow">PANEL DE GEOCHAVÍN</span><h1>Documentar para compartir.</h1><p>Gestiona el inventario y revisa la información antes de publicarla.</p><div class="stats"><?php foreach(['Atractivos'=>'SELECT COUNT(*) n FROM atractivos_turisticos','Coordenadas verificadas'=>'SELECT COUNT(*) n FROM ubicaciones WHERE verificado=1','Servicios'=>'SELECT COUNT(*) n FROM servicios_turisticos'] as $name=>$sql):?><div class="stat"><strong><?=e(one($sql)['n'])?></strong><span><?=e($name)?></span></div><?php endforeach;?></div><div class="info-panel"><h2>Publicar con responsabilidad</h2><ol><li>Registra una fuente oficial y comprueba que el lugar pertenece al distrito.</li><li>Añade coordenadas WGS84 y su procedencia; no uses valores aproximados como verificados.</li><li>Coteja descripciones, fotografías y derechos antes de activar la verificación.</li><li>Activa «Publicado» para que la ficha sea visible. Las fichas pendientes llevan una etiqueta.</li><li>Para itinerarios, crea una ruta provisional, añade puntos ordenados y coteja el conjunto.</li></ol></div><?php });}
function admin_list(array $user,array $defs,string $entity,array $def):void {
 admin_shell($user,$defs,$entity,function()use($entity,$def){$q=mb_substr(query_string('q'),0,120);$p=max(1,(int)query_string('p'));$offset=($p-1)*25;$where='';$params=[];$name=isset($def['fields']['nombre'])?'nombre':(isset($def['fields']['descripcion'])?'descripcion':null);if($q!==''&&$name){$where=" WHERE `$name` LIKE ?";$params[]='%'.$q.'%';}$count=(int)one("SELECT COUNT(*) n FROM `$entity`".$where,$params)['n'];$data=rows("SELECT * FROM `$entity`".$where." ORDER BY id DESC LIMIT 25 OFFSET $offset",$params);?><div class="section-heading"><div><span class="eyebrow">INVENTARIO Y GESTIÓN</span><h1><?=e($def['label'])?></h1></div><a class="button" href="<?=e(url('?page=admin&entity='.$entity.'&action=new'))?>">+ Nuevo registro</a></div><form class="filter-bar"><input type="hidden" name="page" value="admin"><input type="hidden" name="entity" value="<?=e($entity)?>"><label>Buscar<input name="q" maxlength="120" value="<?=e($q)?>"></label><button class="button small">Buscar</button></form><p class="muted"><?=e($count)?> registros</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Registro</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['id'])?></td><td><?=e($r['nombre']??$r['descripcion']??('Ruta '.$r['ruta_id'].' · parada '.$r['orden']))?></td><td><?=array_key_exists('verificado',$r)?badge((bool)$r['verificado']):e(isset($r['activo'])?($r['activo']?'Activo':'Inactivo'):'Registrado')?></td><td><div class="table-actions"><a class="text-link" href="<?=e(url('?page=admin&entity='.$entity.'&action=edit&id='.$r['id']))?>">Editar</a><form method="post" data-confirm="¿Eliminar este registro? Las relaciones dependientes pueden impedir la eliminación."><?=csrf()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><input type="hidden" name="action" value="delete"><button class="text-button danger">Eliminar</button></form></div></td></tr><?php endforeach;if(!$data):?><tr><td colspan="4">No hay registros para mostrar.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><?php if($p>1):?><a href="<?=e(url('?page=admin&entity='.$entity.'&q='.rawurlencode($q).'&p='.($p-1)))?>">← Anterior</a><?php endif;?><span>Página <?=e($p)?></span><?php if($offset+25<$count):?><a href="<?=e(url('?page=admin&entity='.$entity.'&q='.rawurlencode($q).'&p='.($p+1)))?>">Siguiente →</a><?php endif;?></div><?php });
}
function admin_form(array $user,array $defs,string $entity,array $def,int $id,string $error='',array $record=[]):void {admin_shell($user,$defs,$entity,function()use($entity,$def,$id,$error,$record){?><span class="eyebrow"><?=e($def['label'])?></span><h1><?=$id?'Editar registro':'Nuevo registro'?></h1><?php if($error):?><div class="error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" class="editor-form info-panel"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($id)?>"><?php foreach($def['fields'] as $key=>$field):[$label,$type]=$field;$value=$record[$key]??'';$required=($field[3]??false)?'required':'';if($type==='password')$value='';?><label class="<?=$type==='textarea'?'full':''?> <?=$type==='check'?'check-label':''?>"><?php if($type==='check'):?><input type="checkbox" name="<?=e($key)?>" value="1" <?=$value?'checked':''?>><?=e($label)?><?php else:?><?=e($label)?><?php if($type==='textarea'):?><textarea name="<?=e($key)?>" rows="5" maxlength="<?=e($field[2])?>" <?=$required?>><?=e($value)?></textarea><?php elseif($type==='relation'||$type==='select'):$options=$type==='relation'?array_column(rows('SELECT id,nombre FROM `'.$field[2].'` ORDER BY nombre'),'nombre','id'):$field[2];?><select name="<?=e($key)?>" <?=$required?>><option value="">Seleccionar…</option><?php foreach($options as $v=>$labelOpt):?><option value="<?=e($v)?>" <?=(string)$v===(string)$value?'selected':''?>><?=e($labelOpt)?></option><?php endforeach;?></select><?php elseif($type==='integer'||$type==='decimal'):?><input type="number" name="<?=e($key)?>" value="<?=e($value)?>" step="<?=$type==='decimal'?'any':'1'?>" min="<?=e($field[2][0])?>" max="<?=e($field[2][1])?>" <?=$required?>><?php else:?><input type="<?=e($type)?>" name="<?=e($key)?>" value="<?=e($value)?>" maxlength="<?=e($field[2])?>" <?=$required?> <?=$type==='password'?'autocomplete="new-password"':''?>><?php endif;endif;?></label><?php endforeach;if($entity==='ubicaciones'):?><label class="check-label full"><input type="checkbox" name="confirmar_territorio" value="1">Confirmo que cotejé la posición y su pertenencia al distrito de Chavín de Huántar con la fuente indicada. No son datos de ejemplo.</label><?php endif;?><p class="muted small-text full">La publicación y la verificación son decisiones editoriales distintas. La fuente debe ser consultable y pertinente; una URL por sí sola no acredita los datos.</p><div class="form-actions full"><button class="button">Guardar registro →</button><a class="text-link" href="<?=e(url('?page=admin&entity='.$entity))?>">Cancelar</a></div></form><?php });}
function report_data():array {
 $from=query_string('desde')?:date('Y-m-01');$to=query_string('hasta')?:date('Y-m-d');
 foreach([$from,$to] as $d){$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$d);if(!$dt||$dt->format('Y-m-d')!==$d)throw new DomainException('Selecciona fechas válidas (AAAA-MM-DD).');}
 if($from>$to)throw new DomainException('La fecha inicial no puede superar la final.');
 $end=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d');
 $data=rows('SELECT a.id,a.nombre,COUNT(v.id) visualizaciones FROM atractivos_turisticos a LEFT JOIN visitas v ON v.atractivo_id=a.id AND v.fecha>=? AND v.fecha<? GROUP BY a.id,a.nombre ORDER BY visualizaciones DESC,a.nombre',[$from,$end]);return [$from,$to,$data];
}
function report_page():void {
 [$from,$to,$data]=report_data();
 if(query_string('format')==='csv') {header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="geochavin-visitas.csv"');$fp=fopen('php://output','w');fwrite($fp,"\xEF\xBB\xBF");fputcsv($fp,['ID','Atractivo','Visualizaciones','Desde','Hasta'],',','"','');foreach($data as $r){$name=$r['nombre'];if(preg_match('/^[\s]*[=+@-]/u',$name))$name="'".$name;fputcsv($fp,[$r['id'],$name,$r['visualizaciones'],$from,$to],',','"','');}fclose($fp);return;}
 page('Reportes',function()use($from,$to,$data){admin_shell(current_user(),entities(),'report',function()use($from,$to,$data){?><span class="eyebrow">INFORMACIÓN PARA MEJORAR</span><h1>Reportes de visitas.</h1><p>Visualizaciones de fichas deduplicadas por sesión y día. No equivalen a turistas ni visitantes únicos.</p><form class="filter-bar"><input type="hidden" name="page" value="report"><label>Desde<input type="date" name="desde" value="<?=e($from)?>" required></label><label>Hasta<input type="date" name="hasta" value="<?=e($to)?>" required></label><button class="button">Consultar</button><a class="text-link" href="<?=e(url('?page=report&format=csv&desde='.$from.'&hasta='.$to))?>">Descargar CSV ↓</a></form><div class="stats"><div class="stat"><strong><?=array_sum(array_column($data,'visualizaciones'))?></strong><span>Visualizaciones en el período</span></div></div><div class="table-wrap"><table><thead><tr><th>Atractivo</th><th>Visualizaciones</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['visualizaciones'])?></td></tr><?php endforeach;?></tbody></table></div><?php });});
}
